from __future__ import annotations

"""Independent classical single-shear PTMC adapter.

This module implements the phenomenological theory of martensite crystallography
(PTMC) as an independent theory branch.  It intentionally does not import
Cayron CT/CMC/SMC or the Ball--James adapter.

Conventions
-----------
* The crystallographic correspondence maps parent direct coordinates to product
  direct coordinates: ``u_M = C @ u_A``.
* Transformation stretches are represented in the symmetric metric-orthonormal
  parent frame ``B_A = M_A^(1/2)``.
* A martensite variant generated by a parent symmetry ``g`` uses
  ``C_i = C @ g^{-1}``.
* A twinned laminate uses
  ``F_pre(f) = U_base + f a⊗n`` where
  ``R_hat U_other - U_base = a⊗n``.
* A slip lattice-invariant shear specified in the product lattice uses
  ``F_pre(gamma) = (I + gamma s⊗q) U`` with ``s·q = 0`` in the
  deformed product frame.
* Habit compatibility is solved as
  ``R F_pre - delta I = b⊗m``.
  ``delta=1`` is a true invariant-plane strain; ``delta != 1`` is the
  Bowles--Mackenzie uniformly dilated-plane extension.
* OR matrices are reported both in the symmetric metric frames and in the
  repository's PTCLab-style conventional Cartesian frames.

The numerical engine returns every discrete admissible root and explicitly
reports the degenerate continuum case instead of sampling it and pretending the
sample is exhaustive.
"""

from collections.abc import Iterable
from dataclasses import asdict, dataclass
from enum import Enum
from typing import Any

import numpy as np
from scipy.optimize import minimize_scalar

from .correspondence import Correspondence
from .lattice import Lattice
from .numerics import DEFAULT_NUMERICAL_POLICY, NumericalPolicy
from .point_groups import point_group_operations

Array = np.ndarray


class LISType(str, Enum):
    """Classical single-shear lattice-invariant deformation mechanism."""

    TWIN = "twin"
    SLIP = "slip"


@dataclass(frozen=True)
class PTMCVariant:
    """One distinct transformation-stretch variant."""

    index: int
    U: Array
    correspondence_M_from_A: Array
    representative_parent_symmetry_index: int
    generating_parent_symmetry_indices: tuple[int, ...]
    polar_rotation_product_from_parent: Array
    principal_stretches: Array
    determinant: float
    maximum_audit_residual: float


@dataclass(frozen=True)
class PTMCTwinRelation:
    """One exact M/M rank-one relation used as a twinning LIS branch.

    Equation:
        R_hat U_other - U_base = a ⊗ n_reference.
    """

    base_variant_index: int
    other_variant_index: int
    branch: int
    rotation_hat: Array
    a: Array
    n_reference: Array
    deformed_twin_plane_normal_base: Array
    twin_plane_product_crystal_base: Array
    twin_shear_magnitude: float
    rank_one_residual: float
    rotation_residual: float


@dataclass(frozen=True)
class PTMCParameterRoots:
    """Auditable roots of the classical single-shear compatibility polynomial."""

    parameter_name: str
    discrete_roots: tuple[float, ...]
    continuum: bool
    domain: tuple[float, float] | None
    polynomial_coefficients_ascending: tuple[float, float, float]
